# checks/bio.practical2.py: recomputes every number in the Microscopy and drawing chapter.
import importlib.util, os
from math import isclose, pi

n = 0


def eq(label, got, want, tol=1e-9):
    global n
    n += 1
    assert isclose(got, want, rel_tol=0, abs_tol=tol), f"{label}: computed {got}, chapter says {want}"


def sf(x, k=3):
    return float(f"{x:.{k}g}")


# the grid figure is generated by data/fig_bio.practical2.py: use the same dots
here = os.path.dirname(os.path.abspath(__file__))
spec = importlib.util.spec_from_file_location("figp2", os.path.join(here, "..", "data", "fig_bio.practical2.py"))
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)
counts, total = m.grid_counts()
eq("grid A", counts["A"], 6)
eq("grid B", counts["B"], 6)
eq("grid C", counts["C"], 4)
eq("grid D", counts["D"], 4)
eq("grid squares", m.GRID_N ** 2, 36)
eq("grid total", total, 200)
mean = sum(counts.values()) / 4
eq("grid mean", mean, 5.0)
eq("grid estimate", mean * 36, 180)
eq("grid error pc", (200 - 180) / 200 * 100, 10)

# --- warm-up ----------------------------------------------------------------------------------------------
eq("division", 1000 / 100, 10)

# --- plan diagram proportions ------------------------------------------------------------------------------
scale = 60 / 40
eq("scale", scale, 1.5)
eq("cortex", 12 * scale, 18)
eq("pith", 18 * scale, 27)
eq("ring units", 40 - 12 - 18, 10)
eq("ring mm", 10 * scale, 15)
eq("sum", 18 + 27 + 15, 60)

# --- scale bar --------------------------------------------------------------------------------------------
M = 15000 / 100
eq("scale bar M", M, 150)
eq("bundle actual", 36000 / M, 240)
eq("bundle by proportion", 36 / 15 * 100, 240)

# --- graticule --------------------------------------------------------------------------------------------
unit = 7 * 10 / 24
eq("unit", sf(unit, 5), 2.9167)
eq("cell 17 units", sf(17 * unit, 3), 49.6)
eq("cell 2 s.f.", sf(17 * unit, 2), 50)

# --- stomata ------------------------------------------------------------------------------------------------
c = [17, 21, 19, 22, 16]
eq("mean", sum(c) / 5, 19.0)
area = pi * 0.25 ** 2
eq("area", sf(area, 5), 0.19635)
eq("density", sf(19.0 / area, 2), 97)

# --- practice --------------------------------------------------------------------------------------------------
eq("p4 mm", 8.4 / 120, 0.070)
eq("p4 um", 8.4 / 120 * 1000, 70)
eq("p5 unit", 9 * 10 / 30, 3.0)
eq("p5 cell", 22 * 3.0, 66)
cc = [8, 10, 6, 9, 7]
eq("p6 mean", sum(cc) / 5, 8.0)
eq("p6 area", sf(pi * 0.40 ** 2, 5), 0.50265)
eq("p6 density", sf(8.0 / (pi * 0.40 ** 2), 2), 16)
eq("p8 M", 54 / 0.90, 60)

# --- exam practice --------------------------------------------------------------------------------------------
eq("ep1 M", 25000 / 50, 500)
eq("ep1 actual", 40000 / 500, 80)
eq("ep3 unit", sf(5 * 10 / 12, 3), 4.17)
eq("ep3 cell", sf(9.0 * 50 / 12, 2), 38)
eq("ep3 cell exact", 9.0 * 50 / 12, 37.5)
cs = [31, 27, 35, 29, 33]
eq("ep4 mean", sum(cs) / 5, 31.0)
a2 = pi * 0.15 ** 2
eq("ep4 area", sf(a2, 3), 0.0707)
eq("ep4 density", sf(31.0 / a2, 2), 440)
eq("leaf total", 22 + 24 + 6 + 4, 56)
eq("ep6 scale", 112 / 56, 2.0)
eq("palisade", 22 * 2.0, 44)
eq("spongy", 24 * 2.0, 48)
eq("epi", 6 * 2.0, 12)
eq("epi lower", 4 * 2.0, 8)
eq("ep6 sum", 44 + 48 + 12 + 8, 112)
eq("ep7 mm", 22 / 25, 0.88)
eq("ep7 um", 22 / 25 * 1000, 880)

# --- stretch ---------------------------------------------------------------------------------------------------
g = [9, 6, 8, 7, 10]
eq("s1 mean", sum(g) / 5, 8.0)
eq("s1 square area", sf(0.20 ** 2, 2), 0.040)
eq("s1 density", 8.0 / 0.040, 200)
eq("s1 area mm2", 4.5 * 100, 450)
eq("s1 cells", 450 * 200, 9.0e4)

# --- quiz -----------------------------------------------------------------------------------------------------
eq("quiz M", 45 / 0.30, 150)
eq("quiz wrong", sf(0.30 / 45, 2), 0.0067)

print("ok")
